/**
 * @method
 * @name disclosure_type
 * @description disclosure type 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.disclosure_type = function (code) {
    const layer = "layer" + code;
    const imgId = "dTypeImg" + code;
    ($c.util.getComponent("iconBoxLayer") && $c.util.getComponent("iconBoxLayer").hide ? $c.util.getComponent("iconBoxLayer").hide() : console.warn('[sdd] hide 대상 미해결: ' + "iconBoxLayer"));
    const myImg = parseInt(code, 10);
    if ($c.util.getComponent(imgId).value === "on") {
        $c.util.getComponent(imgId).src = "../images/common/puplic" + myImg + "_off.gif";
        $c.util.getComponent(imgId).setValue("off");
    } else {
        $c.util.getComponent(imgId).src = "../images/common/puplic" + myImg + "_on.gif";
        $c.util.getComponent(imgId).setValue("on");
    }
    if ($c.util.getComponent(imgId).value === "on") {
        ($c.util.getComponent(layer) && $c.util.getComponent(layer).show ? $c.util.getComponent(layer).show() : console.warn('[sdd] show 대상 미해결: ' + layer));
    } else {
        if ($c.util.getComponent(imgId).value === "off") {
            ($c.util.getComponent(layer) && $c.util.getComponent(layer).hide ? $c.util.getComponent(layer).hide() : console.warn('[sdd] hide 대상 미해결: ' + layer));
        }
    }
    ($c.util.getComponent("iconBoxLayer") && $c.util.getComponent("iconBoxLayer").show ? $c.util.getComponent("iconBoxLayer").show() : console.warn('[sdd] show 대상 미해결: ' + "iconBoxLayer"));
};

/**
 * @method
 * @name disclosure_window_check
 * @description disclosure window check 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.disclosure_window_check = function (code) {
    const dMom = eval("document.frm.publicAll" + code);
    const dName = eval("document.frm.disclosureTypeArr" + code);
    if (dMom.checked === true) {
        if (dName.length == null) {
            dName.checked = true;
        } else {
            for (let i = 0; i < dName.length; i++) {
                dName[i].checked = true;
            }
        }
    } else {
        if (dName.length == null) {
            dName.checked = false;
        } else {
            for (let j = 0; j < dName.length; j++) {
                dName[j].checked = false;
            }
        }
    }
};

/**
 * @method
 * @name disclosure_window_close
 * @description disclosure window close 처리
 * @param {*} code code
 * @returns {void}
 * @hidden N
 */
scwin.disclosure_window_close = function (code) {
    const layer = "layer" + code;
    const imgId = "dTypeImg" + code;
    ($c.util.getComponent("iconBoxLayer") && $c.util.getComponent("iconBoxLayer").hide ? $c.util.getComponent("iconBoxLayer").hide() : console.warn('[sdd] hide 대상 미해결: ' + "iconBoxLayer"));
    ($c.util.getComponent(layer) && $c.util.getComponent(layer).hide ? $c.util.getComponent(layer).hide() : console.warn('[sdd] hide 대상 미해결: ' + layer));
    const myImg = parseInt(code, 10);
    if ($c.util.getComponent(imgId).value === "on") {
        $c.util.getComponent(imgId).src = "../images/common/puplic" + myImg + "_off.gif";
        $c.util.getComponent(imgId).setValue("off");
    } else {
        $c.util.getComponent(imgId).src = "../images/common/puplic" + myImg + "_on.gif";
        $c.util.getComponent(imgId).setValue("on");
    }
    ($c.util.getComponent("iconBoxLayer") && $c.util.getComponent("iconBoxLayer").show ? $c.util.getComponent("iconBoxLayer").show() : console.warn('[sdd] show 대상 미해결: ' + "iconBoxLayer"));
};

/**
 * @method
 * @name disclosure_window_all_close
 * @description disclosure window all close 처리
 * @returns {void}
 * @hidden N
 */
scwin.disclosure_window_all_close = function () {
    for (let i = 1; i < 12; i++) {
        if (i < 10) {
            let layer = "layer0" + i;
            let imgId = "dTypeImg0" + i;
        } else {
            layer = "layer" + i;
            imgId = "dTypeImg" + i;
        }
        ($c.util.getComponent(layer) && $c.util.getComponent(layer).hide ? $c.util.getComponent(layer).hide() : console.warn('[sdd] hide 대상 미해결: ' + layer));
        if ($c.util.getComponent(imgId).value === "on") {
            $c.util.getComponent(imgId).src = "../images/common/puplic" + i + "_off.gif";
            $c.util.getComponent(imgId).setValue("off");
        }
    }
};

/**
 * @method
 * @name order_by
 * @description order by 처리
 * @param {*} val val
 * @param {*} startVal startVal
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.order_by = async function (val, startVal) {
    $c.util.getComponent('dma_changeBusinessReq').set('orderIndex', val);
    $c.util.getComponent("orderType1").className = "";
    $c.util.getComponent("orderType2").className = "";
    $c.util.getComponent("orderType3").className = "";
    if (val === "") {
        $c.util.getComponent("orderType1").className = "on";
        (document.frm || { elements: [] }).orderMode.value = "1";
    }
    if (val === "1" && $c.util.getComponent("orderType1").className === "") {
        $c.util.getComponent("orderType1").className = "on";
        if (startVal === "ok") {
            await scwin.fncSearch();
        }
    }
    if (val === "2" && $c.util.getComponent("orderType2").className === "") {
        $c.util.getComponent("orderType2").className = "on";
        if (startVal === "ok") {
            await scwin.fncSearch();
        }
    }
    if (val === "3" && $c.util.getComponent("orderType3").className === "") {
        $c.util.getComponent("orderType3").className = "on";
        if (startVal === "ok") {
            await scwin.fncSearch();
        }
    }
};

/**
 * @method
 * @name disclosureSetting
 * @description disclosure Setting 처리
 * @returns {void}
 * @hidden N
 */
scwin.disclosureSetting = function () {
    let get_name = "";
    let set_name = "";
    let check_setting = "";
    for (let i = 1; i < 12; i++) {
        check_setting = "";
        if (i < 10) {
            get_name = eval("document.frm.disclosureTypeArr0" + i);
            set_name = eval("document.frm.pDisclosureType0" + i);
        } else {
            get_name = eval("document.frm.disclosureTypeArr" + i);
            set_name = eval("document.frm.pDisclosureType" + i);
        }
        if (get_name.length == null) {
            if (get_name.checked === true) {
                check_setting = check_setting + get_name.value + "|";
            }
        } else {
            for (let j = 0; j < get_name.length; j++) {
                if (get_name[j].checked === true) {
                    check_setting = check_setting + get_name[j].value + "|";
                }
            }
        }
        set_name.value = check_setting;
    }
};

/**
 * @method
 * @name changeBusiness
 * @description change Business 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeBusiness = async function () {
    // TODO Stage2(규칙19): fieldEl(DOM 요소 계약) → 컴포넌트 getValue/setValue 계약으로 전환 필요
    const obj = ($c.util.fieldEl('slc_business', 'business'));
    if (obj.value === "") {
        ($c.util.getComponent("txt_tableLayer") && $c.util.getComponent("txt_tableLayer").setValue) ? $c.util.getComponent("txt_tableLayer").setValue("업종을 선택해주세요.") : (($c.util.getComponent("txt_tableLayer") && $c.util.getComponent("txt_tableLayer").setText) ? $c.util.getComponent("txt_tableLayer").setText("업종을 선택해주세요.") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "txt_tableLayer"), void ("업종을 선택해주세요.")));
        return false;
    }
    if (obj.value === "03") {
        await $c.win.alert("제조업은 제조업 하위단 메뉴를 선택하셔야 합니다.");
        ($c.util.getComponent("txt_tableLayer") && $c.util.getComponent("txt_tableLayer").setValue) ? $c.util.getComponent("txt_tableLayer").setValue("업종을 선택해주세요.") : (($c.util.getComponent("txt_tableLayer") && $c.util.getComponent("txt_tableLayer").setText) ? $c.util.getComponent("txt_tableLayer").setText("업종을 선택해주세요.") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + "txt_tableLayer"), void ("업종을 선택해주세요.")));
        return false;
    }
    $c.util.getComponent('dma_changeBusinessReq').set('method', "searchDisclosureByIndustryMainSub");
    (document.frm || { elements: [] }).target = "iframe_1";
    await scwin.tx_changeBusiness();
};

